import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.Ce1WstT_.js";const i="/fundsroom_infotech/assets/architecture/database-architecture.svg",u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/database.md","filePath":"system-design/database.md"}'),r={name:"system-design/database.md"};function c(n,e,d,l,h,m){return t(),o("div",null,[...e[0]||(e[0]=[s('<div class="page-header"><span class="category-badge">SYSTEM DESIGN</span><h1>Database Architecture</h1><p class="page-subtitle">Understand the 3NF PostgreSQL schema, relational structures, and immutability strategies for historical data.</p><hr class="header-divider"></div><p>The backend connects directly to a managed Supabase PostgreSQL instance via the <code>pg</code> driver.</p><h2 id="schema-overview-3nf" tabindex="-1">Schema Overview (3NF) <a class="header-anchor" href="#schema-overview-3nf" aria-label="Permalink to &quot;Schema Overview (3NF)&quot;">​</a></h2><p>The database is normalized to Third Normal Form (3NF). Primary keys utilize <code>UUIDv4</code> via <code>gen_random_uuid()</code>.</p><ol><li><strong><code>users</code></strong>: Stores login credentials, hashes, and RBAC roles.</li><li><strong><code>customers</code></strong>: CRM profiles containing contact info and lifecycle status (<code>LEAD</code>, <code>ACTIVE</code>, <code>INACTIVE</code>).</li><li><strong><code>customer_followups</code></strong>: Auditable text logs mapped to specific customers and users.</li><li><strong><code>products</code></strong>: The master catalog tracking names, SKUs, and <code>current_stock</code>.</li><li><strong><code>stock_movements</code></strong>: Immutable ledger tracking every stock change (IN/OUT), quantities, and business reason.</li><li><strong><code>challans</code></strong>: Sales order header records tracking <code>total_quantity</code> and status (<code>DRAFT</code>, <code>CONFIRMED</code>, <code>CANCELLED</code>).</li><li><strong><code>challan_items</code></strong>: Sales order line items containing <strong>immutable snapshots</strong> (<code>snapshot_product_name</code>, <code>snapshot_sku</code>, <code>snapshot_unit_price</code>) protecting historical invoices from master catalog modifications.</li></ol><h2 id="entity-relationship-diagram" tabindex="-1">Entity Relationship Diagram <a class="header-anchor" href="#entity-relationship-diagram" aria-label="Permalink to &quot;Entity Relationship Diagram&quot;">​</a></h2><div class="architecture-container"><img src="'+i+'" alt="Database Architecture ERD"></div><p class="screenshot-caption">Figure 7 — PostgreSQL Entity Relationship Diagram</p><h2 id="indexing" tabindex="-1">Indexing <a class="header-anchor" href="#indexing" aria-label="Permalink to &quot;Indexing&quot;">​</a></h2><p>Indexes are applied to foreign key columns, unique lookups (<code>sku</code>, <code>challan_number</code>), and frequent filters (<code>customer status</code>, <code>mobile</code>).</p>',10)])])}const p=a(r,[["render",c]]);export{u as __pageData,p as default};
